-- GymProgress — base de datos completa con datos de ejemplo
--
-- Crea el esquema entero (10 tablas) y lo llena con:
--   · 2 usuarios listos para entrar
--   · 10 ejercicios en el catálogo
--   · 2 rutinas armadas con sus ejercicios
--   · rachas de 21 días (3 semanas)
--   · 21 días de entrenamientos con sus series
--   · registros de peso corporal
--
-- CÓMO USARLO EN MYSQL WORKBENCH
--   1. Abre este archivo (File > Open SQL Script)
--   2. Ejecútalo entero con el rayo (Ctrl+Shift+Enter)
--   3. Refresca el panel Schemas y verás la base gymprogress
--
-- USUARIOS DE PRUEBA
--   kata@gmail.com / 12345678
--   ana@gmail.com  / 12345678

SET NAMES utf8mb4;

DROP DATABASE IF EXISTS gymprogress;
CREATE DATABASE gymprogress
    CHARACTER SET utf8mb4
    COLLATE utf8mb4_unicode_ci;
USE gymprogress;


-- 1. ESQUEMA

create table cambio_ejercicio (
    series_afectadas integer,
    ejercicio_nuevo_id bigint,
    ejercicio_original_id bigint,
    id bigint not null auto_increment,
    registrado_en datetime(6) not null,
    sesion_id bigint not null,
    tipo varchar(20) not null,
    ejercicio_nuevo_nombre varchar(120),
    ejercicio_original_nombre varchar(120) not null,
    primary key (id)
) engine=InnoDB;

create table ejercicio (
    favorito bit not null,
    requiere_equipo bit not null,
    tempo_concentrico integer,
    tempo_excentrico integer,
    tempo_pausa_abajo integer,
    tempo_pausa_arriba integer,
    id bigint not null auto_increment,
    tipo_entrenamiento varchar(30) not null,
    grupo_muscular varchar(80) not null,
    nombre varchar(120) not null,
    media_url varchar(300),
    descripcion varchar(500),
    primary key (id)
) engine=InnoDB;

create table peso_corporal (
    fecha date not null,
    peso_kg float(53) not null,
    id bigint not null auto_increment,
    usuario_id bigint not null,
    primary key (id)
) engine=InnoDB;

create table racha (
    dias_actuales integer not null,
    dias_maximo integer not null,
    ultimo_entrenamiento date,
    id bigint not null auto_increment,
    usuario_id bigint not null,
    primary key (id)
) engine=InnoDB;

create table rutina (
    activa bit not null,
    creada_en datetime(6) not null,
    id bigint not null auto_increment,
    usuario_id bigint not null,
    tipo varchar(50) not null,
    programa varchar(80) not null,
    nombre varchar(120) not null,
    primary key (id)
) engine=InnoDB;

create table rutina_ejercicio (
    descanso_seg integer not null,
    orden integer not null,
    peso_sugerido_kg float(53),
    reps_objetivo integer not null,
    series integer not null,
    tempo_bajada float(53),
    tempo_fondo float(53),
    tempo_subida float(53),
    tempo_tope float(53),
    ejercicio_id bigint not null,
    id bigint not null auto_increment,
    rutina_id bigint not null,
    primary key (id)
) engine=InnoDB;

create table semana_descarga (
    fin date,
    inicio date,
    reintentar_desde date,
    detectada_en datetime(6) not null,
    id bigint not null auto_increment,
    usuario_id bigint not null,
    estado varchar(20) not null,
    motivo varchar(300) not null,
    primary key (id)
) engine=InnoDB;

create table serie_registrada (
    fallo_muscular bit not null,
    numero_serie integer not null,
    peso_kg float(53) not null,
    repeticiones integer not null,
    ejercicio_id bigint not null,
    id bigint not null auto_increment,
    registrada_en datetime(6) not null,
    sesion_id bigint not null,
    ejercicio_nombre varchar(120),
    primary key (id)
) engine=InnoDB;

create table sesion (
    finalizada_en datetime(6),
    id bigint not null auto_increment,
    iniciada_en datetime(6) not null,
    rutina_id bigint,
    usuario_id bigint not null,
    primary key (id)
) engine=InnoDB;

create table usuario (
    dias_semana integer,
    descanso_automatico bit not null,
    descanso_por_defecto_seg integer not null,
    minutos_sesion integer,
    unidad_peso varchar(2) not null,
    tema varchar(10) not null,
    creado_en datetime(6) not null,
    id bigint not null auto_increment,
    nivel varchar(50),
    token_sesion varchar(64),
    objetivo varchar(80),
    equipamiento varchar(100),
    nombre varchar(100) not null,
    correo varchar(180) not null,
    foto_url varchar(500),
    lesiones varchar(500),
    password varchar(255) not null,
    primary key (id)
) engine=InnoDB;

-- Claves únicas y foráneas

alter table racha add constraint UK1sjgtvirmxa2sve0054nc4wnp unique (usuario_id);
alter table usuario add constraint UKe2vvdmqg7sggm3i991l48tw1x unique (token_sesion);
alter table usuario add constraint UK2mlfr087gb1ce55f2j87o74t unique (correo);
alter table rutina_ejercicio add constraint FKlbaibt7r0i47yof7mmbdwphay foreign key (rutina_id) references rutina (id);
alter table serie_registrada add constraint FKtjjdfyorglrsiitub45awo7s2 foreign key (sesion_id) references sesion (id);

-- Estas relaciones el modelo las guarda como id suelto, así que la
-- integridad se refuerza aquí a mano.
ALTER TABLE rutina ADD CONSTRAINT fk_rutina_usuario
    FOREIGN KEY (usuario_id) REFERENCES usuario (id) ON DELETE CASCADE;
ALTER TABLE sesion ADD CONSTRAINT fk_sesion_usuario
    FOREIGN KEY (usuario_id) REFERENCES usuario (id) ON DELETE CASCADE;
ALTER TABLE racha ADD CONSTRAINT fk_racha_usuario
    FOREIGN KEY (usuario_id) REFERENCES usuario (id) ON DELETE CASCADE;
ALTER TABLE peso_corporal ADD CONSTRAINT fk_peso_usuario
    FOREIGN KEY (usuario_id) REFERENCES usuario (id) ON DELETE CASCADE;
ALTER TABLE semana_descarga ADD CONSTRAINT fk_descarga_usuario
    FOREIGN KEY (usuario_id) REFERENCES usuario (id) ON DELETE CASCADE;
ALTER TABLE rutina_ejercicio ADD CONSTRAINT fk_rutejer_ejercicio
    FOREIGN KEY (ejercicio_id) REFERENCES ejercicio (id);


