-- 10. COMPROBACIÓN

SELECT 'usuarios' AS tabla, COUNT(*) AS registros FROM usuario
UNION ALL SELECT 'ejercicios', COUNT(*) FROM ejercicio
UNION ALL SELECT 'rutinas', COUNT(*) FROM rutina
UNION ALL SELECT 'ejercicios en rutina', COUNT(*) FROM rutina_ejercicio
UNION ALL SELECT 'rachas', COUNT(*) FROM racha
UNION ALL SELECT 'sesiones', COUNT(*) FROM sesion
UNION ALL SELECT 'series', COUNT(*) FROM serie_registrada
UNION ALL SELECT 'pesos', COUNT(*) FROM peso_corporal
UNION ALL SELECT 'cambios de ejercicio', COUNT(*) FROM cambio_ejercicio
UNION ALL SELECT 'semanas de descarga', COUNT(*) FROM semana_descarga;

-- Porcentaje de series al fallo por semana: así se ve la fatiga que
-- hace saltar la sugerencia de descarga.
SELECT
    FLOOR(DATEDIFF(CURDATE(), DATE(s.iniciada_en)) / 7) + 1 AS semana,
    COUNT(*) AS series,
    SUM(sr.fallo_muscular) AS al_fallo,
    ROUND(SUM(sr.fallo_muscular) * 100 / COUNT(*)) AS porcentaje_fallo
FROM sesion s
JOIN serie_registrada sr ON sr.sesion_id = s.id
WHERE s.usuario_id = 1
GROUP BY semana
ORDER BY semana;
